-- Mod-authored natural wonder portrait descriptions, cs_CZ overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Pro tento přírodní div není k dispozici žádný popis."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Obrovský impaktní kráter při pohledu z jeho okraje, rozeklaná mísa vyražená do světlé pouštní země. Blízký svah porůstá zelené křoví, které klesá do zastíněné jámy s dnem v hluboké hnědé tmě, a vzdálený okraj se zvedá v pruzích okrové a zlaté pod zamlženou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Stupňovitá pyramida z ryzího zlata, po jejíž přední stěně vystupuje strmé schodiště k malé svatyni na vrcholu. U její paty jsou mezi štíhlými tmavými stromy navršeny obří zlaté pruty a celý výjev září žlutě, poklad bájného města vyobrazený doslova. Světelné paprsky za pyramidou vypadají jako úsvit prorážející nad ztraceným městem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Pramen neskutečně zářivé tyrkysové vody vyvěrá z pánve na vrcholu útesů z tmavé skály a stéká jako zářící vodopád do jezírka pod nimi. Chomáče zelené trávy se drží černé skály, palmové listy rámují teplou zlatou oblohu a drobné jiskřičky ve vodě prozrazují, že je kouzelná, nikoli přirozená."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Dokonalý sopečný kužel vyplňuje celý obraz a jeho široká sněhová čepice sahá téměř až k úpatí svahů. Sníh je vymalován měkkou bílou a světle modrou před sytě modrou oblohou a podél úpatí hory leží pás zeleného křoví a zamlžené vody."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Gejzír tryská ze zubatého světlého pahorku a jeho bílá tříšť se rozevírá a plní celou oblohu mlhou před modrým pozadím. Z obou stran se tiskne tmavý stálezelený les a popředí tvoří krusta minerálních teras v okrové, žlutohnědé a hnědé barvě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Mohutný vápencový mys se zdvihá z rovného moře, na levé straně strmé světlé útesy a po jeho hřbetu dlouhý svah tmavě zelené vegetace. Celý výjev je zalit zlatem a obloha i voda září jako v pozdním odpoledni."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Obrovská kupole protkaná sněhem vyplňuje horní polovinu obrazu ledovou bílou a modrou barvou a kolem její paty pluje věnec malých mraků. Pod ní se rozprostírá zelená savana, kde dvě žirafy stojí u světlé vodní tůně, a na okrajích výjevu rostou stromy s plochými korunami."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Široké tyrkysové jezero se táhne do dálky ke světlým kopcům na obzoru a po obou stranách ho svírají skalnaté okrové výběžky. Uprostřed v popředí se vynořuje hroch, jehož hlava a hřbet protínají zvlněnou hladinu, pod bílou září světla, která plní oblohu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Stolová hora s plochým vrcholem z vrstevnaté rudooranžové skály se zdvihá o samotě ze suché pláně, pruhované skalní stěny nad dlouhými svahy ze zřícených kamenů. Řídký zelený křovinatý porost je rozseten po písčité půdě u její paty a plochý vrchol ostře rýsuje linii proti jasně modré obloze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Pyramida z pruhované skály a sněhu se zdvihá proti sytě modré obloze a její pruhovaná stěna je z jedné strany osvětlena teplým zlatem. Pod ní je celé popředí tvořeno drsným sněhovým polem a ledovými hřebeny ve studeném modrém stínu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Skupina rozeklaných pouštních štítů z oranžovohnědého pískovce, jejichž stěny rozrývají hluboké rokle, a zpoza prostředního vrcholu se line měkká záře světla. V popředí se na písčité pláni povalují roztroušené balvany pod jasnou modrou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Holá červenohnědá hora, jejíž dolní svahy jsou pohřbeny pod hromadami šedých balvanů se třpytem stříbrné rudy. Po jejím boku se vine stezka, řady tmavých hranatých bloků lemují její úpatí jako důlní díla a prašný vrchol se rýsuje proti modré obloze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Podmořský výjev: korály zaplňují levou stranu a spodek obrazu v oranžové, červené, fialové a světle modré barvě a mezi větvemi stojí vzpřímené trubicovité houby. Hlubokou modrou vodou plují drobné tropické rybky, uprostřed jedna jasně žlutá. Světlo se k pravému hornímu rohu ztrácí v otevřené tmě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Monumentální vstupní brána představující bájné doly: vysoká tmavá pevnostní zeď korunovaná cimbuřím se zlatými špičkami, uprostřed s dveřmi, po stranách s okrovými kamennými věžemi. Před ní je světlá skalní podlaha vytesána do širokých oblouků, jako by byla sama země vylámána do hladka."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Svěže zelená hora se zdvihá k zaoblenému vrcholu, svahy jí pokrývá džungle, jen místy se oranžovohnědá skála prolamuje v útesech. Popředí vyplňují vysoká stébla trávy s drobnými modrými květy a obloha vzadu má sytou tropickou tyrkysovou barvu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Obrovský červený monolit leží napříč středním plánem, jeho oblá pískovcová hmota je rozbrázděná svislými žlaby a ve světle září oranžově. Před ním se rozkládá rovinatý buš, červená půda posetá nízkým zeleným křovím a chomáči trávy, pod jasně modrou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Tmavý sopečný kužel se zdvihá z moře za pásem světle tyrkysové vody, při pohledu z džunglového břehu, jehož široké zelené listy rámují výjev. Obloha nad ním hoří sírovou žlutí a slabý závit kouře nad vrcholem naznačuje blížící se erupci."
